    return s.data.site_xpos[site].copy(),s.data.site_xmat[site].reshape(3,3).copy()

def move(s,p=None,R=None,g=None,n=60,arm='right',left=None):
    a=s.targets.copy(); k=0 if arm=='right' else 6
    if p is not None:a[k:k+3]=Rb.T@(np.array(p)-pb)
    if R is not None:a[k+3:k+6]=Rot.from_matrix(Rb.T@R).as_rotvec()
    if g is not None:a[12+k:18+k]=g
    if left is not None:a[6:12]=left
    old=s.targets.copy()
    rots={j:Slerp([0,1],Rot.from_rotvec([old[j+3:j+6],a[j+3:j+6]])) for j in [0,6]}
    for i in range(n):
        t=(i+1)/n; t=t*t*(3-2*t)
        act=old*(1-t)+a*t
        for j in [0,6]:act[j+3:j+6]=rots[j](t).as_rotvec()
        s.step(act)
    print('step',len(s.actions),'obj',body(s),'wrist',pose(s)[0],'success',s.success,flush=True)

def hold(s,n=20):
